  h+='<div class="tm396-card"><div class="tm396-cardhead"><div><h4>Today Daily Report</h4><p>Manual work plus automatic enrollment data.</p></div><input id="tm396DailyDate" type="date" value="'+esc(todayMY())+'" style="height:34px;border:1px solid var(--border);border-radius:9px;background:var(--bg-elevated);color:var(--text-primary);padding:0 9px;font-size:8px"></div><div class="tm396-breakdown"><div class="tm396-bitem"><span>Leads / Messages</span><b>'+fmt(man.leads)+' / '+fmt(man.messages_sent)+'</b></div><div class="tm396-bitem"><span>Calls / Follow-ups</span><b>'+fmt(man.calls_made)+' / '+fmt(man.follow_ups)+'</b></div><div class="tm396-bitem"><span>Registrations</span><b>'+fmt(aut.registrations)+'</b></div><div class="tm396-bitem"><span>VIP / IB</span><b>'+fmt(man.vip_converted)+' / '+fmt(man.ib_shifts)+'</b></div><div class="tm396-bitem"><span>B2 / B3</span><b>'+fmt(aut.batch2_enrollments)+' / '+fmt(aut.batch3_enrollments)+'</b></div><div class="tm396-bitem"><span>Fund / Advance</span><b>'+fmt(aut.fundamental_enrollments)+' / '+fmt(num(aut.advance_enrollments)+num(aut.advance_fundamental_enrollments))+'</b></div></div></div></div>';
  h+='<div class="tm396-card"><div class="tm396-cardhead"><div><h4>Source Performance</h4><p>Which channel is producing results in '+esc(range.label)+'.</p></div></div><div class="tm396-breakdown">'+(sources.length?sources.map(x=>'<div class="tm396-bitem"><span>'+esc(x.source)+'</span><b>'+fmt(x.leads)+' leads</b><small>'+fmt(x.converted)+' converted · '+fmt(x.conversion)+'%</small></div>').join(''):'<div class="tm396-empty">No source activity in this range.</div>')+'</div></div>';
  h+='<div class="tm396-card"><div class="tm396-cardhead"><div><h4>Client Work — Full Detail</h4><p>Status, follow-up, source, course, broker and contact. Admin mirror is read-only.</p></div><div class="tm396-clienttools"><input id="tm396ClientSearch" placeholder="Search name, ID, WhatsApp, course…"><select id="tm396ClientStatus"><option value="">All Statuses</option><option value="new">New</option><option value="contacted">Contacted</option><option value="interested">Interested</option><option value="follow_up">Follow-up</option><option value="converted">Converted</option><option value="not_interested">Not Interested</option></select></div></div><div class="tm396-tablewrap"><table class="tm396-table"><thead><tr><th>Client</th><th>Source / Campaign</th><th>Course</th><th>Status</th><th>Follow-up</th><th>Broker</th><th>Assigned</th><th>Note</th><th>Contact</th></tr></thead><tbody id="tm396ClientRows"></tbody></table></div></div>';
